-- Look and feel: general + decoration
-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/

-- Border / shadow colours live in colours.lua, generated by `theme-apply`
-- from themes/<name>/theme.conf. The fallback below keeps Hyprland usable
-- if the generated file is missing.
local ok, theme = pcall(require, "colors")
if not ok or type(theme) ~= "table" then
	theme = {
		active_border = { colors = { "rgba(88c0d0ee)", "rgba(5e81acee)" }, angle = 135 },
		inactive_border = "rgba(4c566add)",
		shadow = 0xee1a1a1a,
	}
end

hl.config({
	general = {
		gaps_in = 5,
		gaps_out = 10,

		border_size = 2,

		col = {
			active_border = theme.active_border,
			inactive_border = theme.inactive_border,
		},

		-- Set to true to enable resizing windows by clicking and dragging on borders and gaps
		resize_on_border = false,

		-- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
		allow_tearing = false,

		layout = "dwindle",
	},

	decoration = {
		rounding = 5,
		rounding_power = 2,

		-- Change transparency of focused and unfocused windows
		active_opacity = 1.0,
		inactive_opacity = 1.0,

		shadow = {
			enabled = true,
			range = 4,
			render_power = 3,
			color = theme.shadow,
		},

		blur = {
			enabled = true,
			size = 3,
			passes = 1,
			vibrancy = 0.1696,
		},
	},
})
